import{t as e}from"./buildPage-DWQZYYcs.js";var t=e({slug:`linkedin-scraper`,heroTitle:`Find LinkedIn contacts in minutes`,heroSubtitle:`Perplexity Computer analyzes a LinkedIn company page, identifies likely decision-makers, and packages verified contact research into an import-ready prospect list.`,inputUrlCta:`Find my contacts`,inputUrlPlaceholder:`linkedin.com/company/example`,inputUrlPrefill:`Go to {url} and build a contact list from this LinkedIn company page. (1) Identify the most relevant decision-makers by function and seniority for outreach. (2) Research each person across public sources and trusted contact databases to find verified work emails, phone numbers when available, and LinkedIn profile URLs. (3) Organize the results into a clean CSV-style table with name, title, company, email, phone, and profile link. (4) Flag uncertain matches or missing data clearly. (5) Deliver a short summary of the best contacts to approach first and why they matter.`,heroOverlaySteps:[`Reviewing the company page and mapping the most relevant decision-makers`,`Researching verified emails, phone numbers, and profile links across trusted sources`,`Scoring which contacts are most likely to be high-value outreach targets`,`Prospect list with contact details and priority notes ready to import`],generatingSteps:[`Visiting {url} to understand the company and the functions to prioritize`,`Designing an agent to identify likely decision-makers and validate contact data`,`Configuring contact-table output with confidence checks and missing-data flags`,`Packaging the work into an outreach-ready CSV-style list with priority notes`],featureSectionTitle:`From company page to prospect list`,featureCardTitles:[`Connects to your outbound workflow`,`Outputs your team can use`],featureCardDescriptions:[`Computer splits the job into company research, contact identification, data verification, and list packaging so prospecting stays structured instead of manual.`,`Sheets, CRMs, Notion, and sales planning tools can stay connected so the contact list moves straight into your outbound workflow.`,`Decision-maker lists. Verified emails. Phone numbers when available. Priority notes. Computer gives you a prospecting package your team can act on immediately.`],capabilitySectionTitle:`Your lead researcher, on autopilot`,capabilitySectionSubtitle:`Paste a company page, step away, and come back to a cleaner prospect list.`,capabilityCards:[{title:`Contact Discovery`,description:`Computer can identify the decision-makers most relevant to your offer and organize them by role, seniority, and likely buying influence.`},{title:`Contact Verification`,description:`Computer can research work emails, phone numbers, and profile links across multiple sources and clearly flag anything uncertain.`},{title:`Priority Targeting`,description:`Computer can highlight which contacts look most valuable to approach first so your team spends time on the strongest leads.`},{title:`Connect Your Tools`,description:`Computer can organize the research into Sheets, CRMs, Notion, and other outbound tools so handoff takes minutes instead of hours.`},{title:`Clean Table Output`,description:`Computer can package every record into an import-ready contact table with titles, links, confidence notes, and missing-data flags.`},{title:`Repeat the Workflow`,description:`Computer can rerun the research for new accounts and refresh old lists when people change roles or new prospects appear.`}]});export{t as default};
